public class G32CommerceWebStore {
 public static Boolean observe() {
  WebStore value = new WebStore(Name='Synthetic store', OptionsAutoFacetingEnabled=true);
  System.assertEquals(true,value.OptionsAutoFacetingEnabled);
  value.OptionsAutoFacetingEnabled=false; System.assertEquals(false,value.OptionsAutoFacetingEnabled);
  value.put('OptionsAutoFacetingEnabled', true); System.assertEquals(true,value.get('OptionsAutoFacetingEnabled'));
  Map<String,Schema.SObjectField> fields=Schema.SObjectType.WebStore.fields.getMap();
  System.assertEquals(true,fields.containsKey('OptionsAutoFacetingEnabled'));
  System.assertEquals(false,fields.containsKey('OptionsSyntheticMissing'));
  Schema.DescribeFieldResult d=fields.get('OptionsAutoFacetingEnabled').getDescribe();
  System.assertEquals(Schema.DisplayType.BOOLEAN,d.getType());
  System.assertEquals(false,d.isNillable());
  return true;
 }
}
